protocol OrderPublishing { func publish(_ order: Order) async throws }

final class MQTTOrderAdapter: OrderPublishing {
    private let connection: MQTTConnection
    init(connection: MQTTConnection) { self.connection = connection }
    func publish(_ order: Order) async throws {
        try await connection.publish(to: "orders", qos: .atLeastOnce,
            payload: ByteBuffer(data: try JSONEncoder().encode(order)))
    }
}
